import crypto from "crypto";

const WEBHOOK_SECRET = "whsec_zealt_test_secret_key_5f2a9c";

function computeSignature(body) {
  return "sha256=" + crypto
    .createHmac("sha256", WEBHOOK_SECRET)
    .update(body)
    .digest("hex");
}

async function runTests() {
  const url = "http://localhost:5173/webhook";

  // Test 1: Missing X-Signature-256 header
  console.log("Test 1: Missing X-Signature-256 header");
  try {
    const res = await fetch(url, {
      method: "POST",
      body: JSON.stringify({ event: "test", items: [1, 2, 3] }),
    });
    console.log(`Status: ${res.status} (expected: 401)`);
  } catch (err) {
    console.error(err);
  }

  // Test 2: Invalid signature
  console.log("Test 2: Invalid signature");
  try {
    const res = await fetch(url, {
      method: "POST",
      headers: {
        "X-Signature-256": "sha256=invalid_signature_hex_value",
      },
      body: JSON.stringify({ event: "test", items: [1, 2, 3] }),
    });
    console.log(`Status: ${res.status} (expected: 401)`);
  } catch (err) {
    console.error(err);
  }

  // Test 3: Valid signature, valid payload
  console.log("Test 3: Valid signature, valid payload");
  try {
    const body = JSON.stringify({ event: "order.created", items: ["item1", "item2"] });
    const signature = computeSignature(body);
    const res = await fetch(url, {
      method: "POST",
      headers: {
        "X-Signature-256": signature,
        "Content-Type": "application/json",
      },
      body,
    });
    console.log(`Status: ${res.status} (expected: 200)`);
    const json = await res.json();
    console.log("Response JSON:", json);
  } catch (err) {
    console.error(err);
  }

  // Test 4: Valid signature, invalid JSON
  console.log("Test 4: Valid signature, invalid JSON");
  try {
    const body = "{ invalid json }";
    const signature = computeSignature(body);
    const res = await fetch(url, {
      method: "POST",
      headers: {
        "X-Signature-256": signature,
      },
      body,
    });
    console.log(`Status: ${res.status} (expected: 400)`);
  } catch (err) {
    console.error(err);
  }

  // Test 5: Valid signature, invalid payload schema
  console.log("Test 5: Valid signature, invalid payload schema");
  try {
    const body = JSON.stringify({ event: 123, items: "not an array" });
    const signature = computeSignature(body);
    const res = await fetch(url, {
      method: "POST",
      headers: {
        "X-Signature-256": signature,
        "Content-Type": "application/json",
      },
      body,
    });
    console.log(`Status: ${res.status} (expected: 400)`);
  } catch (err) {
    console.error(err);
  }
}

runTests();

